CREATE TABLE orch_runs ( run_id text PRIMARY KEY CHECK (trim(run_id) <> ''), generated_at TEXT NOT NULL, document_version integer NOT NULL CHECK (document_version >= 1), provenance TEXT NOT NULL CHECK (json_type(provenance) = 'object'), document TEXT NOT NULL CHECK (json_type(document) = 'object'), item_count integer NOT NULL CHECK (item_count >= 0), CONSTRAINT orch_runs_document_identity_check CHECK ( ( json_extract(document, '$.runId') = run_id AND (length(CAST(json_extract(document, '$.version') AS TEXT)) >= 1 AND CAST(json_extract(document, '$.version') AS TEXT) NOT GLOB '*[^0-9]*') AND CAST(json_extract(document, '$.version') AS INTEGER) = document_version ) IS TRUE ) );
CREATE TABLE orch_items ( id text PRIMARY KEY CHECK (trim(id) <> ''), tier text NOT NULL CHECK (tier IN ('needsDrew', 'needsOrchestrator')), kind text NOT NULL CHECK (trim(kind) <> ''), title text NOT NULL, source text NOT NULL, state text CHECK (state IS NULL OR trim(state) <> ''), reason text NOT NULL, ref text, since TEXT NOT NULL, last_seen_at TEXT NOT NULL, item TEXT NOT NULL CHECK (json_type(item) = 'object'), first_seen_run_id text NOT NULL REFERENCES orch_runs (run_id) ON DELETE RESTRICT, last_seen_run_id text NOT NULL REFERENCES orch_runs (run_id) ON DELETE RESTRICT, CONSTRAINT orch_items_seen_order_check CHECK (last_seen_at >= since), CONSTRAINT orch_items_document_identity_check CHECK ((json_extract(item, '$.id') = id) IS TRUE) );
CREATE INDEX orch_items_tier_state_idx ON orch_items (tier, state);
CREATE INDEX orch_items_last_seen_run_idx ON orch_items (last_seen_run_id);
